#!/usr/bin/env bash
# Seed a Playbook edition into LOCAL wrangler KV — the keyless dev path.
# Use this to publish an edition generated by hand or by a Claude agent
# (the "agent-as-editorial-board" flow) without an ANTHROPIC_API_KEY.
#
# Usage:
#   scripts/seed-edition.sh <edition.json> [lore.json] [date]
#
#   <edition.json>  required — an edition object matching src/schema.ts (Edition type)
#   [lore.json]     optional — updated lore matching src/seed-lore.json shape
#   [date]          optional — YYYY-MM-DD; defaults to the edition's meta.date
#
# Example:
#   scripts/seed-edition.sh workers/playbook-engine/fixtures/edition-2026-07-02.json \
#                           workers/playbook-engine/fixtures/lore.seed.json
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENGINE_DIR="$REPO_ROOT/workers/playbook-engine"

EDITION="${1:?Usage: seed-edition.sh <edition.json> [lore.json] [date]}"
LORE="${2:-}"
DATE="${3:-}"

[ -f "$EDITION" ] || { echo "edition file not found: $EDITION" >&2; exit 1; }
python3 -m json.tool "$EDITION" >/dev/null || { echo "edition is not valid JSON" >&2; exit 1; }

# Derive the date from the edition unless one was passed.
if [ -z "$DATE" ]; then
  DATE="$(python3 -c "import json,sys;print(json.load(open(sys.argv[1]))['meta']['date'])" "$EDITION")"
fi

# Resolve paths to absolutes so wrangler (run from the engine dir) finds them.
EDITION_ABS="$(cd "$(dirname "$EDITION")" && pwd)/$(basename "$EDITION")"

kv() { npx wrangler kv key put "$1" "$@" --binding PLAYBOOK --local; }

cd "$ENGINE_DIR"
echo "Seeding edition $DATE into local KV…"
npx wrangler kv key put "latest"          --path "$EDITION_ABS" --binding PLAYBOOK --local
npx wrangler kv key put "edition:$DATE"    --path "$EDITION_ABS" --binding PLAYBOOK --local
npx wrangler kv key put "editions:index"   "[\"$DATE\"]"          --binding PLAYBOOK --local

if [ -n "$LORE" ] && [ -f "$LORE" ]; then
  python3 -m json.tool "$LORE" >/dev/null || { echo "lore is not valid JSON" >&2; exit 1; }
  LORE_ABS="$(cd "$(dirname "$LORE")" && pwd)/$(basename "$LORE")"
  npx wrangler kv key put "lore"           --path "$LORE_ABS"    --binding PLAYBOOK --local
  echo "Seeded lore."
fi

echo "Done. Restart 'npm run engine:dev' if it was already running, then load /playbook."
